// The golden synth rows as JS: "s <scenario> <index> <f32 bits>", "op ...",
// "len ...", read from test/golden/synth.march (generated by the real Swift).
import { readFileSync } from "node:fs";
import { join } from "node:path";

// ---- The golden: rows "s <scenario> <index> <f32 bits>", "op ...", "len ..." ----
function goldenRows(root) {
  const text = readFileSync(join(root, "test", "golden", "synth.march"), "utf8");
  const rows = [];
  for (const m of text.matchAll(/"((?:[^"\\]|\\.)*)"/g)) {
    for (const line of m[1].split("\\n")) if (line.length) rows.push(line.split(" "));
  }
  return rows;
}

const HOLES = { gutter: "Gutter", ring10: "Ring10", ring20: "Ring20", ring30: "Ring30", ring40: "Ring40", ring50: "Ring50", pocketLeft: "PocketLeft", pocketRight: "PocketRight" };
const BARE = { launch: "SndLaunch", rail: "SndRail", hump: "SndHump", lip: "SndLip", backwall: "SndBackwall", landed: "SndLanded", gutter: "SndGutter", hop: "SndHop", whoosh: "SndWhoosh", hotSpot: "SndHotSpot", lever: "SndLever", reelTick: "SndReelTick", reelStop: "SndReelStop", frameDone: "SndFrameDone", lineWon: "SndLineWon", jackpot: "SndJackpot", foul: "SndFoul" };
const WITH_INT = { pullWin: "SndPullWin", combo: "SndCombo", tallyChips: "SndTallyChips", tallyMult: "SndTallyMult" };

// A golden cue as March's JS value of Skee.Cues.Sound.
function soundOf(tokens) {
  const [name, arg] = tokens;
  if (tokens.length === 1 && BARE[name]) return { $: BARE[name] };
  if (name === "drop" && HOLES[arg]) return { $: "SndDrop", _0: { $: HOLES[arg] } };
  if (WITH_INT[name] && tokens.length === 2) return { $: WITH_INT[name], _0: Number(arg) };
  if (name === "banner" && tokens.length === 2) return { $: "SndBanner", _0: arg.replace(/~/g, " ") };
  return null;
}

// Scenarios that are one cue on a fresh synth, then only rendering.
export function scenarios(root) {
  const by = new Map();
  for (const r of goldenRows(root)) {
    if (!["op", "s", "len"].includes(r[0])) continue;
    if (!by.has(r[1])) by.set(r[1], { name: r[1], ops: [], kept: [], len: 0 });
    const s = by.get(r[1]);
    if (r[0] === "op") s.ops.push(r.slice(3));
    else if (r[0] === "s") s.kept.push([Number(r[2]), parseInt(r[3], 16)]);
    else s.len = Number(r[2]);
  }
  const out = [];
  for (const s of by.values()) {
    if (s.ops.length < 2 || s.ops[0][0] !== "play") continue;
    if (!s.ops.slice(1).every((o) => o[0] === "render")) continue;
    const sound = soundOf(s.ops[0].slice(1));
    if (sound) out.push({ name: s.name, sound, len: s.len, kept: s.kept });
  }
  return out;
}

const f32 = new Float32Array(1), u32 = new Uint32Array(f32.buffer);
export const fromBits = (b) => { u32[0] = b; return f32[0]; };
export const bitsOf = (x) => { f32[0] = x; return u32[0]; };

